      title="Edit Comment"
      submitButton={
        <Button
          isLoading={updateCommentMutation.isPending}
          form="edit-comment"
          type="submit"
          size="sm"
          disabled={updateCommentMutation.isPending}
        >
          Update
        </Button>
      }
    >
      <Form
        id="edit-comment"
        onSubmit={(values) => {
          updateCommentMutation.mutate({
            commentId,
            data: values,
          });
        }}
        schema={updateCommentInputSchema}
        options={{
          defaultValues: {
            body: initialBody,
          },
        }}
      >
        {({ register, formState }) => (
          <Textarea
            label="Body"
            error={formState.errors['body']}
            registration={register('body')}
          />
        )}
      </Form>
    </FormDrawer>
  );
};
