import { useUpdateComment, updateCommentInputSchema } from '../api/update-comment';

type EditCommentProps = {
  commentId: string;
  discussionId: string;
  initialBody: string;
};

export const EditComment = ({
  commentId,
  discussionId,
  initialBody,
}: EditCommentProps) => {
  const { addNotification } = useNotifications();
  const updateCommentMutation = useUpdateComment({
    discussionId,
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'Comment Updated',
        });
      },
    },
  });

  // Reset the isDone state when the component unmounts or when the drawer closes
  // This allows the drawer to be opened again if needed (though usually we reload data)
  useEffect(() => {
    return () => {
      // Optional: handle cleanup if necessary
    };
  }, []);

  // Note: We rely on the FormDrawer's internal state for isOpen, but we need to
  // clear the success state so the drawer can be reopened if the user tries to edit
  // again (or if we want to show the form again). However, typically after success
  // we might just show the updated list. The user requirement says "Show a success
  // message after saving".

