  // Let's stick to the mutation result for simplicity, as in CreateComment.
  // If the user wants to edit again, they might need to refresh or we can add an
  // explicit reset.
  // Actually, let's look at the `useDisclosure` hook in `FormDrawer`. It has `close()`
  // and `open()`. The `isDone` prop calls `close()`.
  // To allow reopening, we should probably manage the `isDone` state manually or
  // accept that it won't reopen until the next render if `isSuccess` is true.
  // A better UX often includes an "Edit" button that reopens the drawer.
  // Let's just pass `updateCommentMutation.isSuccess` for now.

  return (
    <FormDrawer
      isDone={updateCommentMutation.isSuccess}
      triggerButton={
        <Button variant="ghost" size="sm" icon={<Pencil className="size-4" />}>
          Edit
        </Button>
